-- Generated by Supabase declarative sync; equivalent posts_content_length rewrite omitted after review.
SET local check_function_bodies = off;

CREATE OR REPLACE FUNCTION private.claim_notification_pushes (
  receipts boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  jobs jsonb;
begin
  with candidates as (
    select d.id from private.notification_push_deliveries d
    where d.state = case when receipts then 'receipt' else 'pending' end
      and d.available_at <= now() and (d.leased_until is null or d.leased_until <= now())
    order by d.available_at, d.id limit 100 for update skip locked
  ), claimed as (
    update private.notification_push_deliveries d
    set lease_id = gen_random_uuid(), leased_until = now() + interval '5 minutes', attempts = attempts + 1
    from candidates c where d.id = c.id returning d.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', d.id::text, 'lease_id', d.lease_id, 'ticket_id', d.ticket_id,
    'allowed', private.push_notification_allowed(n.id, t.id),
    'expired', n.created_at <= now() - interval '24 hours',
    'token', t.token, 'recipient_id', n.recipient_id, 'post_id', p.id::text, 'post_type', p.type,
    'title', case when n.type = 'vote_ended' then '투표가 종료됐어요.' else n.title end,
    'body', case when n.type = 'vote_ended' then '내 투표 결과를 확인해 보세요.' else n.body end
  ) order by d.id), '[]'::jsonb) into jobs
  from claimed d join private.notifications n on n.id = d.notification_id
  join private.posts p on p.id = n.post_id join public.push_tokens t on t.id = d.token_id;
  return jobs;
end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_post_liked()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
begin
  select * into target from private.posts where id = new.post_id;
  if target.notice_title is not null or target.type <> 'post' or target.deleted_at is not null or
     target.hidden_at is not null or (select count(*) from private.post_likes l where l.post_id = new.post_id) <> 10 then
    return new;
  end if;
  -- 목록과 Push 본문은 글 앞 20자에 안내 문장을 붙인다. 20자를 넘으면 ...으로 줄인다.
  -- shortcut: 코드포인트로 잘라 20자 경계의 조합 이모지가 깨질 수 있다. 문제가 되면 grapheme 기준으로 자른다.
  insert into private.notifications(recipient_id, type, post_id, title, body, event_key)
  values (target.author_id, 'post_liked', target.id, '내 게시글에 10개 이상의 좋아요가 달렸어요.',
          '''' || case when char_length(private.notification_text(target.content)) > 20
                       then rtrim(left(private.notification_text(target.content), 20)) || '...'
                       else private.notification_text(target.content) end ||
          ''' 게시글에 달린 좋아요를 확인해 보세요.', 'like10:' || target.id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;
